def stage_context(name: str, plural: str, question: str) -> dict:
    """Minimal valid StageContext for a mirrored method (doctrine lives elsewhere)."""
    return {
        "extraction": {"analysis_type": name, "analysis_type_plural": plural, "core_question": question},
        "curation": {"item_type": name, "item_type_plural": plural},
        "concretization": {},
        "skip_concretization": True,
    }


def E(key, name, family, category, kind, organ, runs_at, description, question, focus, outputs, lineage, *, status="live", sync="mirrored", grounding=None, version=1):
    from src.story.demands import DEMANDS

    return dict(
        source_demands=DEMANDS.get(key, []),
        engine_key=key, engine_name=name, description=description, version=version,
        category=category, kind=kind, family=family, reasoning_domain=f"{family} · {organ}",
        researcher_question=question,
        stage_context=stage_context(name, name + "s", question),
        canonical_schema={},
        extraction_focus=focus, primary_output_modes=outputs, paradigm_keys=[],
        added_date="2026-09-04", source_file=lineage[0] if lineage else None,
        engine_profile=None, apps=[], function=None,
        home_organ=organ, runs_at=runs_at, lineage_refs=lineage, status=status, sync=sync,

    )


